        tracker = e;
        break;
      }
      if (!tracker) {
        ae.effects.push({
          key: SHADOW_CLOAK_REARM_KEY,
          turnsLeft: SHADOW_CLOAK_REARM_TURNS,
          potency: 1,
          stacks: 1,
          sourceId: id,
        });
      } else {
        tracker.turnsLeft = SHADOW_CLOAK_REARM_TURNS;
        tracker.potency = 1;
        tracker.stacks = 1;
      }
