    entityId: id,
    reason: String(context.reason || "offense"),
    mode: String(context.mode || "melee"),
    targetId: Number(context.targetId || 0) | 0,
    at: pos ? { x: pos.x | 0, y: pos.y | 0 } : null,
    hidden: true,
    ambushConsumed,
  });
  return { hidden: true, ambushConsumed };
}

