      if (!e || typeof e !== "object") continue;
      const eKey = normalizeKey(e.key);
      if (!eKey) continue;
      if (!isDotEffectKey(eKey)) continue;
      if (familyKeyFor(eKey) !== family) continue;
      matches.push(i);
    }

